package worker

import "golang.org/x/sys/windows/registry"

// osMachineSource returns the Windows installation's MachineGuid, generated at setup and
// regenerated by sysprep, so a cloned image is detected. The 64-bit registry view is read
// explicitly so a 32-bit build sees the same value.
func osMachineSource() string {
	k, err := registry.OpenKey(registry.LOCAL_MACHINE, `SOFTWARE\Microsoft\Cryptography`, registry.QUERY_VALUE|registry.WOW64_64KEY)
	if err != nil {
		return ""
	}
	defer k.Close()
	v, _, err := k.GetStringValue("MachineGuid")
	if err != nil {
		return ""
	}
	return v
}
